#include "Filter246Effect.h"
#include "Element246Control.h"
#include <iostream>
#include <memory>
#include <stdexcept>
#include <vector>
using namespace pocket;
static void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}
static std::array<int16_t,4> controls(int fx){switch(fx){case 1:return nitro246Defaults;case 2:return delay246Defaults;case 3:return grid246Defaults;case 4:return phone246Defaults;case 5:return spring246Defaults;case 6:return cwo246Defaults;default:return filter246Defaults;}}
int main(int argc,char**){try{const bool quick=argc>1;std::array<int16_t,8192> sine{};for(size_t i=0;i<sine.size();++i)sine[i]=int16_t(std::lround(32767*std::sin(i*6.283185307179586/sine.size())));
 auto tick=[&](Filter246Effect& bus,float input,int fx,bool enabled,const Element246FxAudio* modulation,float external){return bus.next(input,enabled,controls(fx),sine,fx==1,fx==2,fx==3,fx==4,fx==5,fx==6,nullptr,nullptr,modulation,external);};
 // At the native rate the external stream must be sample-aligned, not its peak.
 for(int fx=0;fx<7;++fx)for(int colour:{2,3}){auto actual=std::make_unique<Filter246Effect>(),expected=std::make_unique<Filter246Effect>();actual->prepare(44100);expected->prepare(44100);Element246FxAudio snapshot{{},1,-24000,colour};for(int n=0;n<2048;++n){const int16_t input=int16_t(9000*std::sin(n*.13)),external=int16_t(-12000+2000*std::cos(n*.071));const auto word=reference::element246FxSample(input,external,snapshot.inputs,1,snapshot.amount,colour);tick(*actual,input/32768.f,fx,true,&snapshot,external/32768.f);tick(*expected,word/32768.f,fx,true,nullptr,0);if(actual->cursor==0)check(actual->history==expected->history,"Element external stream is not aligned before the FX kernel");}}
 // Equal carrier/sidechain must match Self through both resamplers at every rate.
 for(double rate:{32000.,44100.,48000.,88200.,96000.,176400.,192000.})for(int colour:{2,3}){auto externalBus=std::make_unique<Filter246Effect>(),selfBus=std::make_unique<Filter246Effect>();externalBus->prepare(rate);selfBus->prepare(rate);Element246FxAudio external{{},1,-24000,colour},self{{},3,-24000,colour};for(int n=0;n<2048;++n){const float input=float(.25*std::sin(n*.173)-.1*std::cos(n*.031));const auto a=tick(*externalBus,input,0,true,&external,input),b=tick(*selfBus,input,0,true,&self,0);check(a==b&&externalBus->history==selfBus->history,"Element external resampling differs from carrier clock/phase/quantization");}}
 auto render=[&](double rate,int fx,int source,int colour,int partition,bool automate,bool enabled){auto bus=std::make_unique<Filter246Effect>();bus->prepare(rate);Element246Control frontend;std::vector<float> audio;audio.reserve(4096);for(int start=0;start<4096;start+=partition)for(int n=start;n<std::min(start+partition,4096);++n){const int amount=automate&&n>=1537?-24000:24000;const float external=float(.35*std::sin(n*.071));frontend.next(true,source,amount,3,colour,18000,external,.65f,.25f,44100./(64*rate));Element246FxAudio snapshot{frontend.inputs,source,int16_t(amount),colour};const float value=tick(*bus,float(.2*std::cos(n*.031)),fx,enabled,&snapshot,external);check(std::isfinite(value)&&std::abs(value)<8,"Element FX output invalid");audio.push_back(value);}check(bus->latency==Filter246Effect::latencyFor(rate)&&bus->underruns==0,"Element FX changed latency or underruns");bus->reset();frontend.next(false,0,0,0,0,0,0,0,0,1);check(!frontend.active&&bus->externalPrevious==0,"Element FX reset retains frontend/sidechain");for(auto& f:bus->externalFilters)check(f.z1==0&&f.z2==0,"Element FX reset retains external filter memory");return audio;};
 size_t cases=0;for(double rate:{32000.,44100.,48000.,88200.,96000.,176400.,192000.})if(!quick||rate==48000.)for(int fx=0;fx<7;++fx)for(int source=0;source<4;++source)for(int colour:{2,3})for(bool enabled:{false,true}){const auto a=render(rate,fx,source,colour,64,true,enabled),b=render(rate,fx,source,colour,257,true,enabled),neutral=render(rate,fx,source,colour,64,false,enabled);check(a==b,"Element FX depends on host partition");check(std::equal(a.begin(),a.begin()+1537,neutral.begin()),"Element FX automation affects earlier audio");check(enabled?a!=neutral:a==neutral,"Element FX automation/bypass mismatch");++cases;}
 // Source 3 ignores the published level word; amount zero is wet silence vs dry.
 reference::Element246Inputs inputs{};for(int source=0;source<4;++source)for(int sample:{-32768,-1,0,1,32767}){check(reference::element246FxSample(int16_t(sample),12345,inputs,source,0,2)==0,"Element FX Multiply zero amount must silence");check(reference::element246FxSample(int16_t(sample),12345,inputs,source,0,3)==sample,"Element FX Subtract zero amount must preserve input");}auto changed=inputs;changed.level=32767;for(int colour:{2,3})check(reference::element246FxSample(12000,5000,inputs,3,24000,colour)==reference::element246FxSample(12000,5000,changed,3,24000,colour),"Element FX self source uses level producer");
 auto bus=std::make_unique<Filter246Effect>();bus->prepare(96000);Element246FxAudio ext{{},1,24000,2};for(float nonfinite:{std::numeric_limits<float>::infinity(),-std::numeric_limits<float>::infinity(),std::numeric_limits<float>::quiet_NaN()})for(int n=0;n<512;++n)check(std::isfinite(tick(*bus,.1f,0,true,&ext,nonfinite)),"Element FX external non-finite input escapes guard");
 std::cout<<"PASS: "<<cases<<" Element FX rate/effect/source/curve/bypass cases; exact 64/257 audio, aligned signed external sidechain and Q15 histories, automation, PDC, reset, non-finite guards and source-3 self contract\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
